import { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { RoomEnvironment } from 'three/examples/jsm/environments/RoomEnvironment.js';

function createBallpit(canvas, config = {}) {
  const renderer = new THREE.WebGLRenderer({
    canvas,
    antialias: true,
    alpha: true,
  });

  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setSize(canvas.clientWidth, canvas.clientHeight);

  const scene = new THREE.Scene();

  const camera = new THREE.PerspectiveCamera(
    50,
    canvas.clientWidth / canvas.clientHeight,
    0.1,
    100
  );
  camera.position.z = 15;

  const pmrem = new THREE.PMREMGenerator(renderer);
  scene.environment = pmrem.fromScene(new RoomEnvironment()).texture;

  const ambient = new THREE.AmbientLight(0xffffff, 0.6);
scene.add(ambient);

const light = new THREE.PointLight(0xffffff, 300);
light.position.set(5, 5, 10);
scene.add(light);

  const geometry = new THREE.SphereGeometry(1, 32, 32);
  const colors = [
  '#7c3aed', // purple
  '#ffffff', // white
  '#1e1e1e', // dark
  '#4f46e5', // blue-purple
];

function getRandomColor() {
  return colors[Math.floor(Math.random() * colors.length)];

  };

  const count = config.count || 40;
  const meshes = [];

  for (let i = 0; i < count; i++) {
    const meshes = [];

const colors = [
  '#7c3aed',
  '#ffffff',
  '#4f46e5',
  '#111827'
];

for (let i = 0; i < count; i++) {

  const material = new THREE.MeshStandardMaterial({
    color: new THREE.Color(colors[Math.floor(Math.random() * colors.length)]),
    roughness: 0.3,
    metalness: 0.6,
  });

  const mesh = new THREE.Mesh(geometry, material);

  mesh.position.set(
    (Math.random() - 0.5) * 10,
    (Math.random() - 0.5) * 10,
    (Math.random() - 0.5) * 5
  );

  scene.add(mesh);
  meshes.push(mesh);
}
  }

  const velocities = meshes.map(() => ({
    x: (Math.random() - 0.5) * 0.05,
    y: (Math.random() - 0.5) * 0.05,
    z: (Math.random() - 0.5) * 0.05,
  }));

  function animate() {
    requestAnimationFrame(animate);

    meshes.forEach((mesh, i) => {
      const v = velocities[i];

      mesh.position.x += v.x;
      mesh.position.y += v.y;
      mesh.position.z += v.z;

      if (Math.abs(mesh.position.x) > 5) v.x *= -1;
      if (Math.abs(mesh.position.y) > 5) v.y *= -1;
      if (Math.abs(mesh.position.z) > 3) v.z *= -1;
    });

    renderer.render(scene, camera);
  }

  animate();

  function resize() {
    const width = canvas.clientWidth;
    const height = canvas.clientHeight;

    renderer.setSize(width, height);
    camera.aspect = width / height;
    camera.updateProjectionMatrix();
  }

  window.addEventListener('resize', resize);

  return {
    dispose() {
      window.removeEventListener('resize', resize);
      renderer.dispose();
    },
  };
}

const Ballpit = ({ className = '', ...props }) => {
  const canvasRef = useRef(null);
  const instanceRef = useRef(null);

  useEffect(() => {
    if (!canvasRef.current) return;

    instanceRef.current = createBallpit(canvasRef.current, props);

    return () => {
      instanceRef.current?.dispose();
    };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      className={className}
      style={{ width: '100%', height: '100%' }}
    />
  );
};

export default Ballpit;
